export type LeaseReleaseStatus = "completed" | "failed" | "uncertain";

export type AccountActivationOperations = {
  readDatabaseActive: (userId: string) => Promise<boolean>;
  setAuthBanned: (userId: string, banned: boolean) => Promise<void>;
  /**
   * Fenced CMS status transition. The operation ID generated by
   * synchronizeAccountActivation must be forwarded to the database so the RPC
   * can verify lease ownership inside the same transaction that updates
   * users.is_active.
   */
  setDatabaseActive: (userId: string, isActive: boolean, operationId: string) => Promise<void>;
  // Optional cross-instance serialization helpers.
  acquireLease?: (userId: string, operationId: string, ttlSeconds: number) => Promise<boolean>;
  renewLease?: (userId: string, operationId: string, ttlSeconds: number) => Promise<boolean>;
  releaseLease?: (
    userId: string,
    operationId: string,
    status: LeaseReleaseStatus,
    error?: string,
  ) => Promise<boolean | void>;
  // Optional reconciliation helper for ambiguous Auth outcomes.
  readAuthBanned?: (userId: string) => Promise<boolean>;
  // Tunable for tests. Production defaults are intentionally conservative.
  leaseTtlSeconds?: number;
  renewalIntervalMs?: number;
};

export class AccountActivationError extends Error {
  readonly uncertain: boolean;
  constructor(message: string, uncertain = false) {
    super(message);
    this.uncertain = uncertain;
  }
}

export const DEFAULT_LEASE_TTL_SECONDS = 30;
export const DEFAULT_RENEWAL_INTERVAL_MS = 8000;

type LeaseHeartbeat = {
  stop: () => void;
  lost: () => boolean;
  error: () => unknown;
};

function normalizeNumber(value: number | undefined, fallback: number, minimum: number): number {
  return typeof value === "number" && Number.isFinite(value) && value >= minimum ? value : fallback;
}

/**
 * Renew the lease periodically while a long-running Auth request is in flight.
 * We cannot cancel a request already sent to Supabase Auth, but we can make sure
 * a lost lease is detected before the CMS status is updated.
 */
function startLeaseHeartbeat(
  operations: AccountActivationOperations,
  userId: string,
  operationId: string,
  ttlSeconds: number,
  intervalMs: number,
): LeaseHeartbeat {
  let lost = false;
  let lastError: unknown = null;

  const timer = setInterval(() => {
    if (lost || !operations.renewLease) return;
    void Promise.resolve()
      .then(() => operations.renewLease!(userId, operationId, ttlSeconds))
      .then((renewed) => {
        if (!renewed && !lost) {
          lost = true;
          lastError = new Error("Account activation lease renewal was rejected.");
        }
      })
      .catch((error) => {
        if (!lost) {
          lost = true;
          lastError = error;
        }
      });
  }, intervalMs);

  const maybeUnref = timer as unknown as { unref?: () => void };
  if (typeof maybeUnref.unref === "function") maybeUnref.unref();

  return {
    stop: () => clearInterval(timer),
    lost: () => lost,
    error: () => lastError,
  };
}

/** Keep the Auth ban and CMS active flag aligned, compensating after DB failure. */
export async function synchronizeAccountActivation(
  userId: string,
  isActive: boolean,
  operations: AccountActivationOperations,
): Promise<void> {
  const operationId = crypto.randomUUID();
  const ttlSeconds = normalizeNumber(operations.leaseTtlSeconds, DEFAULT_LEASE_TTL_SECONDS, 5);
  const renewalIntervalMs = Math.max(
    10,
    Math.min(
      normalizeNumber(operations.renewalIntervalMs, DEFAULT_RENEWAL_INTERVAL_MS, 10),
      Math.floor((ttlSeconds * 1000) / 2),
    ),
  );

  let leaseHeld = false;
  let outcome: LeaseReleaseStatus = "completed";
  let outcomeError: string | undefined;

  const uncertain = (message: string) => new AccountActivationError(message, true);

  const assertLeaseOwned = async (context: string): Promise<void> => {
    if (!leaseHeld || !operations.renewLease) return;
    let renewed: boolean;
    try {
      renewed = await operations.renewLease(userId, operationId, ttlSeconds);
    } catch {
      throw uncertain(
        `Account activation lease could not be renewed ${context}. Reconcile this account before retrying.`,
      );
    }
    if (!renewed) {
      throw uncertain(
        `Account activation lease was lost ${context}. Reconcile this account before retrying.`,
      );
    }
  };

  if (operations.acquireLease) {
    let acquired = false;
    try {
      acquired = await operations.acquireLease(userId, operationId, ttlSeconds);
    } catch {
      throw uncertain(
        "Account activation could not acquire its lease. Reconcile this account before retrying.",
      );
    }
    if (!acquired) {
      throw uncertain(
        "Account activation is already in progress or awaiting reconciliation. Reconcile the account before retrying.",
      );
    }
    leaseHeld = true;
  }

  try {
    // Confirms the account exists and the database is reachable before touching Auth.
    await operations.readDatabaseActive(userId);
    await assertLeaseOwned("before the Auth update");

    let heartbeat: LeaseHeartbeat | null = null;
    let authFailure: unknown = null;
    if (leaseHeld && operations.renewLease) {
      heartbeat = startLeaseHeartbeat(
        operations,
        userId,
        operationId,
        ttlSeconds,
        renewalIntervalMs,
      );
    }

    try {
      await operations.setAuthBanned(userId, !isActive);
    } catch (error) {
      authFailure = error ?? new Error("Auth update failed.");
    } finally {
      heartbeat?.stop();
    }

    if (heartbeat?.lost()) {
      throw uncertain(
        "Account activation lease was lost while the Auth request was running. The Auth outcome is uncertain; reconcile this account.",
      );
    }

    if (authFailure !== null) {
      await assertLeaseOwned("after the Auth request");

      // A timed-out Auth request is ambiguous. Read the real Auth state before
      // deciding whether the requested change actually landed.
      let actualBanned: boolean | null = null;
      if (operations.readAuthBanned) {
        try {
          actualBanned = await operations.readAuthBanned(userId);
        } catch {
          actualBanned = null;
        }
      }

      if (actualBanned === null) {
        throw uncertain(
          "Status outcome is uncertain. Reconcile the user row and Auth ban state.",
        );
      }
      if (actualBanned !== !isActive) {
        throw uncertain(
          "Auth access could not be confirmed. Reconcile the user row and Auth ban state before retrying.",
        );
      }
      // Auth already matches the requested state (for example the write landed
      // but the response timed out). Continue to the fenced database update.
    }

    await assertLeaseOwned("before the database update");

    try {
      await operations.setDatabaseActive(userId, isActive, operationId);
    } catch {
      let persistedAfterFailure: boolean | null = null;
      try {
        persistedAfterFailure = await operations.readDatabaseActive(userId);
      } catch {
        persistedAfterFailure = null;
      }

      if (persistedAfterFailure === null) {
        throw uncertain(
          "Database outcome is uncertain. Reconcile the user row and Auth ban state.",
        );
      }

      if (persistedAfterFailure === isActive) {
        // The write may have committed before the response was lost. Only treat
        // it as confirmed while this operation still owns the lease.
        await assertLeaseOwned("after the database update");
        outcome = "completed";
        return;
      }

      // The write did not land. Restore Auth only while this operation still
      // owns the lease; otherwise reconciliation is authoritative.
      await assertLeaseOwned("before compensating the Auth state");
      try {
        await operations.setAuthBanned(userId, !persistedAfterFailure);
      } catch {
        throw uncertain(
          "Database rejected the status change and Auth compensation could not be confirmed. Reconcile this account.",
        );
      }

      outcome = "failed";
      outcomeError =
        "Database rejected the status change; Auth access was restored to match the CMS status.";
      throw new AccountActivationError(outcomeError);
    }
  } catch (error) {
    if (error instanceof AccountActivationError) {
      if (error.uncertain) outcome = "uncertain";
      else outcome = "failed";
      outcomeError = error.message;
    } else {
      outcome = "uncertain";
      outcomeError = "Account activation failed with an unexpected error.";
    }
    throw error;
  } finally {
    if (leaseHeld && operations.releaseLease) {
      try {
        await operations.releaseLease(userId, operationId, outcome, outcomeError);
      } catch {
        // Best-effort release. Expiry plus administrator reconciliation is the
        // recovery path if the release itself fails.
      }
    }
  }
}
